function normalize(str) {
  return String(str || '')
    .toLowerCase()
    .normalize('NFD')
    .replace(/[\u0300-\u036f]/g, '')
    .replace(/đ/g, 'd')
    .replace(/Đ/g, 'D')
    .trim();
}

function getTelegramContext(source) {
  const payload = source.payload || {};
  const message = source.message || payload.message || payload.body?.message || {};
  const chatId = source.chatId || message.chat?.id || payload.chatId || '';
  const rawText = String(
    source.rawText ||
    source.text ||
    message.text ||
    message.caption ||
    payload.text ||
    ''
  ).trim();

  return { payload, message, chatId, rawText };
}

function cleanName(value) {
  return String(value || '')
    .trim()
    .replace(/^[\"'“”‘’]+|[\"'“”‘’]+$/g, '')
    .replace(/\s+/g, ' ');
}

const source = $('Execute Workflow Trigger').item.json || {};
const ctx = getTelegramContext(source);
const raw = ctx.rawText;
const normalized = normalize(raw);
const prefixes = ['tao doc', 'tao tai lieu', 'create doc'];
let body = raw;
for (const prefix of prefixes) {
  if (normalized.startsWith(prefix + ' ')) {
    body = raw.slice(prefix.length + 1).trim();
    break;
  }
}

let title = cleanName(source.title || source.docTitle || source.fileName || source.documentTitle || '');
let content = source.content || source.docContent || '';

if (!title && body) {
  const markerMatch = body.match(/\s+(?:noi dung|nội dung|content)\s*[:=-]?\s*/i);
  if (markerMatch) {
    const idx = markerMatch.index || 0;
    title = cleanName(body.slice(0, idx));
    content = String(content || body.slice(idx + markerMatch[0].length)).trim();
  } else if (body.includes(':')) {
    const idx = body.indexOf(':');
    title = cleanName(body.slice(0, idx));
    content = String(content || body.slice(idx + 1)).trim();
  } else {
    title = cleanName(body);
  }
}

return [{
  json: {
    ...source,
    payload: ctx.payload,
    message: ctx.message,
    chatId: ctx.chatId,
    rawText: raw,
    text: normalized,
    title,
    content: String(content || ''),
    hasTarget: Boolean(title),
    response: title ? '' : '📝 <b>Tao Google Doc</b>\n\nVi du: <code>tao doc Project Plan noi dung Muc tieu du an</code>'
  }
}];

function escapeHtml(value = '') {
  return String(value)
    .replace(/&/g, '&amp;')
    .replace(/</g, '&lt;')
    .replace(/>/g, '&gt;')
    .replace(/\"/g, '&quot;');
}

const source = $('Prepare Action').item.json || {};
const created = $('Docs Create File').item.json || {};
const title = created.name || source.title || 'Khong ro ten';
const docId = created.id || '';
const link = created.webViewLink || (docId ? `https://docs.google.com/document/d/${docId}/edit` : '');
const contentLength = String(source.content || '').length;

if (!source.chatId) {
  throw new Error('Missing chatId while formatting Google Docs create response.');
}

let text = '✅ <b>Da tao Google Doc</b>\n\n';
text += `<b>${escapeHtml(title)}</b>\n`;
if (docId) text += `ID: <code>${escapeHtml(docId)}</code>\n`;
if (contentLength) text += `Noi dung ban dau: ${contentLength} ky tu\n`;
if (link) text += `🔗 <a href="${escapeHtml(link)}">Mo tai lieu</a>`;

return [{ json: { chatId: source.chatId, text: text.trim() } }];
